using System.Collections.Generic;

using NUnit.Framework;

namespace VcuSwimLab.Calibration.Tests
{
    /// <summary>
    /// Holds the C# runtime to the Python offline implementation, value for value.
    /// </summary>
    /// <remarks>
    /// The fixture is generated by `Analysis/make_runtime_parity_fixture.py`, which computes
    /// every expected value by calling `calibration_study.logscore`, `.centroids`, `.classify`
    /// and `.trial_vote` -- the functions the published results were produced with. Nothing in
    /// the fixture is a description of the algorithm; it is the algorithm's output.
    ///
    /// Two claims are checked separately, because they can fail for different reasons:
    ///
    ///   - against `expected_f64`, that the arithmetic is the same arithmetic;
    ///   - against `expected_f32`, that the runtime reaches the same *decisions* as the
    ///     offline pipeline, which carries float32 from the ONNX output onwards.
    ///
    /// Bit-exact agreement is not claimed. NumPy's vectorised `log` and .NET's `Math.Log`
    /// differ by around an ulp, so magnitudes are compared to 1e-12 and decisions exactly.
    /// </remarks>
    public class PythonParityTests
    {
        private const double Tolerance = 1e-12;

        private static Dictionary<string, object> fixture;

        private static Dictionary<string, object> Fixture
        {
            get
            {
                if (fixture == null)
                {
                    fixture = MiniJson.AsObject(
                        MiniJson.Parse(TestPaths.ReadParityFixture()), "parity fixture");
                }

                return fixture;
            }
        }

        private static List<object> Array(Dictionary<string, object> map, string key)
            => MiniJson.AsArray(MiniJson.Field(map, key, "fixture"), key);

        private static double Number(Dictionary<string, object> map, string key)
            => MiniJson.AsDouble(MiniJson.Field(map, key, "fixture"), key);

        private static int Integer(Dictionary<string, object> map, string key)
            => (int)Number(map, key);

        private static string Text(Dictionary<string, object> map, string key)
            => MiniJson.AsString(MiniJson.Field(map, key, "fixture"), key);

        private static bool Flag(Dictionary<string, object> map, string key)
            => (bool)MiniJson.Field(map, key, "fixture");

        private static double[] Doubles(List<object> list)
        {
            var values = new double[list.Count];
            for (int i = 0; i < list.Count; ++i) values[i] = MiniJson.AsDouble(list[i], "value");
            return values;
        }

        private static float[] Floats(List<object> list)
        {
            var values = new float[list.Count];
            for (int i = 0; i < list.Count; ++i) values[i] = (float)MiniJson.AsDouble(list[i], "score");
            return values;
        }

        private static string[] Strings(List<object> list)
        {
            var values = new string[list.Count];
            for (int i = 0; i < list.Count; ++i) values[i] = MiniJson.AsString(list[i], "name");
            return values;
        }

        // ------------------------------------------------------------------ preconditions

        [Test]
        public void The_fixture_was_generated_against_this_build_s_constants()
        {
            Assert.AreEqual("runtime-calibration-parity-v1", Text(Fixture, "schema_version"));
            Assert.AreEqual(CalibrationMath.Epsilon, Number(Fixture, "epsilon"));
            Assert.AreEqual(CalibrationMath.FrozenHybridAlpha, Number(Fixture, "frozen_alpha"));
            Assert.AreEqual(PersonalCentroidBuilder.RequiredTicksPerCentroid,
                            Integer(Fixture, "ticks_required_per_centroid"));
            CollectionAssert.AreEqual(PopulationProfile.ExpectedClassOrder,
                                      Strings(Array(Fixture, "class_order")));
        }

        [Test]
        public void The_fixture_pins_the_same_population_artifact_the_build_ships()
        {
            var profile = PopulationProfile.Parse(TestPaths.ReadPopulationArtifact());

            Assert.AreEqual(profile.SemanticSha256, Text(Fixture, "population_semantic_sha256"));
            Assert.AreEqual(profile.ConversionSha256, Text(Fixture, "population_conversion_sha256"),
                            "the fixture was generated against a different artifact; regenerate it");
        }

        [Test]
        public void The_scored_tick_window_matches()
        {
            var ticks = Array(Fixture, "scored_ticks");

            Assert.AreEqual(9, ticks.Count);
            for (int i = 0; i < ticks.Count; ++i)
            {
                int tick = (int)MiniJson.AsDouble(ticks[i], "tick");
                Assert.AreEqual(i + 1, tick);
                Assert.IsTrue(PersonalCentroidBuilder.IsScoredTick(tick));
            }

            Assert.IsFalse(PersonalCentroidBuilder.IsScoredTick(0));
        }

        // -------------------------------------------------------------------- unit cases

        [Test]
        public void The_log_score_transform_matches_python()
        {
            var unit = MiniJson.AsObject(MiniJson.Field(
                MiniJson.AsObject(MiniJson.Field(Fixture, "unit_cases", "fixture"), "unit_cases"),
                "logscore", "unit_cases"), "logscore");

            var input = Doubles(Array(unit, "input"));
            var expected = Doubles(Array(unit, "expected"));

            var scores = new float[input.Length];
            for (int i = 0; i < input.Length; ++i) scores[i] = (float)input[i];

            var actual = CalibrationMath.LogScore(scores);

            for (int i = 0; i < expected.Length; ++i)
            {
                Assert.AreEqual(expected[i], actual[i], Tolerance,
                                $"log-score of {input[i]}");
            }
        }

        [Test]
        public void Cosine_similarity_matches_python()
        {
            var unit = MiniJson.AsObject(MiniJson.Field(
                MiniJson.AsObject(MiniJson.Field(Fixture, "unit_cases", "fixture"), "unit_cases"),
                "cosine", "unit_cases"), "cosine");

            double expected = Number(unit, "expected");
            double actual = CalibrationMath.CosineSimilarity(
                Doubles(Array(unit, "a")), Doubles(Array(unit, "b")));

            Assert.AreEqual(expected, actual, Tolerance);
        }

        [Test]
        public void The_centroid_tie_resolves_the_way_python_resolves_it()
        {
            var unit = MiniJson.AsObject(MiniJson.Field(
                MiniJson.AsObject(MiniJson.Field(Fixture, "unit_cases", "fixture"), "unit_cases"),
                "centroid_tie", "unit_cases"), "centroid_tie");

            var rows = Array(unit, "centroids");
            var centroids = new double[rows.Count][];
            for (int e = 0; e < rows.Count; ++e)
            {
                centroids[e] = Doubles(MiniJson.AsArray(rows[e], $"centroids[{e}]"));
            }

            var result = CalibrationMath.Nearest(centroids, Doubles(Array(unit, "feature")));

            Assert.AreEqual(Integer(unit, "expected_class_index"), result.ClassIndex);
            Assert.AreEqual(Number(unit, "expected_margin"), result.Margin, Tolerance);
        }

        [Test]
        public void Every_trial_vote_case_matches_python()
        {
            var cases = MiniJson.AsArray(MiniJson.Field(
                MiniJson.AsObject(MiniJson.Field(Fixture, "unit_cases", "fixture"), "unit_cases"),
                "trial_vote", "unit_cases"), "trial_vote");

            Assert.Greater(cases.Count, 0);

            foreach (object entry in cases)
            {
                var test = MiniJson.AsObject(entry, "trial_vote case");
                string name = Text(test, "name");

                var votes = new List<TickVote>();
                foreach (object t in Array(test, "ticks"))
                {
                    var tick = MiniJson.AsObject(t, "tick");
                    votes.Add(new TickVote(Integer(tick, "tick"), Integer(tick, "class_index")));
                }

                var vote = TrialMajority.Vote(votes, PopulationProfile.ExpectedClassOrder.Length);

                Assert.AreEqual(Integer(test, "expected_class_index"), vote.ClassIndex, name);
                Assert.AreEqual(Flag(test, "expected_tie"), vote.TieOccurred, name);
            }
        }

        // ------------------------------------------------------------------ full sessions

        [Test]
        public void Every_recorded_session_case_matches_python()
        {
            var cases = Array(Fixture, "cases");
            Assert.Greater(cases.Count, 0, "the fixture holds no cases");

            var classNames = Strings(Array(Fixture, "class_order"));
            string artifact = TestPaths.ReadPopulationArtifact();

            foreach (object entry in cases)
            {
                var test = MiniJson.AsObject(entry, "case");
                string name = Text(test, "name");
                var mode = ModeOf(Text(test, "mode"));

                var population = CalibrationModes.UsesPopulation(mode)
                    ? PopulationProfile.Parse(artifact)
                    : null;

                var calibrator = RuntimeCalibrator.Create(mode, classNames, population);

                var recording = MiniJson.AsObject(
                    MiniJson.Field(test, "recording", name), $"{name}.recording");

                foreach (object t in MiniJson.AsArray(
                             MiniJson.Field(recording, "calibration", name), "calibration"))
                {
                    var trial = MiniJson.AsObject(t, "calibration trial");
                    int prompted = Integer(trial, "prompted");

                    foreach (object k in Array(trial, "ticks"))
                    {
                        var tick = MiniJson.AsObject(k, "tick");
                        calibrator.ObserveCalibrationTick(
                            prompted, Integer(tick, "tick"), Floats(Array(tick, "scores")));
                    }
                }

                calibrator.Seal();
                Assert.IsTrue(calibrator.CalibrationValid,
                              $"{name}: {calibrator.CalibrationError}");

                var expected64 = MiniJson.AsObject(
                    MiniJson.Field(test, "expected_f64", name), $"{name}.expected_f64");
                var expected32 = MiniJson.AsObject(
                    MiniJson.Field(test, "expected_f32", name), $"{name}.expected_f32");

                AssertCentroids(name, expected64, calibrator);
                AssertTicks(name, recording, expected64, expected32, calibrator,
                            classNames.Length);
            }
        }

        private static CalibrationMode ModeOf(string name)
        {
            switch (name)
            {
                case CalibrationModes.RawName: return CalibrationMode.Raw;
                case CalibrationModes.PersonalName: return CalibrationMode.Personal;
                case CalibrationModes.PopulationName: return CalibrationMode.Population;
                case CalibrationModes.HybridName: return CalibrationMode.Hybrid;
                default: throw new AssertionException($"the fixture names an unknown mode '{name}'");
            }
        }

        private static void AssertCentroids(string name, Dictionary<string, object> expected,
                                            RuntimeCalibrator calibrator)
        {
            var rows = Array(expected, "centroids");
            var actual = calibrator.ActiveCentroidsForTesting();

            Assert.AreEqual(rows.Count, actual.Length, $"{name}: centroid count");

            for (int e = 0; e < rows.Count; ++e)
            {
                var row = Doubles(MiniJson.AsArray(rows[e], $"centroids[{e}]"));
                for (int i = 0; i < row.Length; ++i)
                {
                    Assert.AreEqual(row[i], actual[e][i], Tolerance,
                                    $"{name}: centroid[{e}][{i}]");
                }
            }
        }

        private static void AssertTicks(string name, Dictionary<string, object> recording,
                                        Dictionary<string, object> expected64,
                                        Dictionary<string, object> expected32,
                                        RuntimeCalibrator calibrator, int classCount)
        {
            var expectedTicks = Array(expected64, "ticks");
            var decisions32 = Array(expected32, "ticks");
            var expectedTrials = Array(expected64, "trials");

            var byTrial = new Dictionary<int, List<TickVote>>();
            var actual = new List<(int Trial, int Tick, TickCalibration Result)>();

            foreach (object t in MiniJson.AsArray(
                         MiniJson.Field(recording, "evaluation", name), "evaluation"))
            {
                var trial = MiniJson.AsObject(t, "evaluation trial");
                int trialId = Integer(trial, "trial_id");

                foreach (object k in Array(trial, "ticks"))
                {
                    var tick = MiniJson.AsObject(k, "tick");
                    int index = Integer(tick, "tick");

                    // The fixture carries tick 0 as the recording does; the offline analysis
                    // drops it from the evaluation split, so the runtime must too.
                    if (!PersonalCentroidBuilder.IsScoredTick(index)) continue;

                    var result = calibrator.Classify(index, Floats(Array(tick, "scores")));
                    Assert.IsTrue(result.Scored, $"{name}: trial {trialId} tick {index}");

                    actual.Add((trialId, index, result));

                    if (!byTrial.TryGetValue(trialId, out var votes))
                    {
                        votes = new List<TickVote>();
                        byTrial[trialId] = votes;
                    }

                    votes.Add(new TickVote(index, result.ClassIndex));
                }
            }

            Assert.AreEqual(expectedTicks.Count, actual.Count, $"{name}: scored tick count");
            Assert.AreEqual(decisions32.Count, actual.Count, $"{name}: float32 tick count");

            for (int i = 0; i < actual.Count; ++i)
            {
                var want = MiniJson.AsObject(expectedTicks[i], "tick");
                var want32 = MiniJson.AsObject(decisions32[i], "tick");
                var got = actual[i];
                string where = $"{name}: trial {got.Trial} tick {got.Tick}";

                Assert.AreEqual(Integer(want, "trial"), got.Trial, $"{where} (trial order)");
                Assert.AreEqual(Integer(want, "tick"), got.Tick, $"{where} (tick order)");

                Assert.AreEqual(Integer(want, "class_index"), got.Result.ClassIndex,
                                $"{where}: float64 prediction");
                Assert.AreEqual(Integer(want32, "class_index"), got.Result.ClassIndex,
                                $"{where}: the float32 offline pipeline decided differently");

                Assert.AreEqual(Number(want, "winner_similarity"), got.Result.WinnerSimilarity,
                                Tolerance, $"{where}: winner similarity");
                Assert.AreEqual(Number(want, "runner_up_similarity"), got.Result.RunnerUpSimilarity,
                                Tolerance, $"{where}: runner-up similarity");
                Assert.AreEqual(Number(want, "margin"), got.Result.Margin, Tolerance,
                                $"{where}: margin");
            }

            var decisions32Trials = Array(expected32, "trials");
            Assert.AreEqual(expectedTrials.Count, byTrial.Count, $"{name}: trial count");

            for (int i = 0; i < expectedTrials.Count; ++i)
            {
                var want = MiniJson.AsObject(expectedTrials[i], "trial");
                var want32 = MiniJson.AsObject(decisions32Trials[i], "trial");
                int trialId = Integer(want, "trial");

                Assert.IsTrue(byTrial.ContainsKey(trialId), $"{name}: no ticks for trial {trialId}");

                var vote = TrialMajority.Vote(byTrial[trialId], classCount);
                string where = $"{name}: trial {trialId}";

                Assert.IsTrue(vote.Scorable, where);
                Assert.AreEqual(Integer(want, "class_index"), vote.ClassIndex,
                                $"{where}: trial-majority prediction");
                Assert.AreEqual(Integer(want32, "class_index"), vote.ClassIndex,
                                $"{where}: the float32 offline pipeline voted differently");
                Assert.AreEqual(Flag(want, "tie"), vote.TieOccurred, $"{where}: tie flag");
                Assert.AreEqual(Integer(want, "scored_ticks"), vote.ScoredTicks,
                                $"{where}: scored tick count");
            }
        }
    }
}
